cd open-etf-agent
npm ci --ignore-scripts --no-audit --no-fund
npm run build
npm run demo -- --case document-compare`
const copyState = ref('')
async function copyQuickstart() {
  try { await navigator.clipboard.writeText(quickstart); copyState.value = 'copied' }
  catch { copyState.value = 'select' }
}
</script>

